// Generates src/generated/{schema,resources}.ts from spec/openapi.json, the
// OpenAPI document cultus derives from its own code (cultus: make openapi).
//
//   pnpm generate                  # from spec/openapi.json
//   pnpm generate --spec <path|url> # refresh spec/openapi.json first
//   pnpm generate --check          # fail if the generated files are stale
//
// Only operations with x-linkvite-visibility "public" and an x-linkvite-sdk
// name ("namespace.method") become SDK methods. Path params become leading
// positional arguments (in path order), then the request body, then the query
// object, then per-request options.
import {readFile, writeFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
import openapiTS, {astToString} from 'openapi-typescript';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const args = process.argv.slice(2);
const check = args.includes('--check');
const specArg = args.includes('--spec')
	? args[args.indexOf('--spec') + 1]
	: null;
const specPath = path.join(root, 'spec/openapi.json');

if (specArg) {
	const text = /^https?:/.test(specArg)
		? await (await fetch(specArg)).text()
		: await readFile(specArg, 'utf8');
	JSON.parse(text);
	await writeFile(specPath, text);
}
const spec = JSON.parse(await readFile(specPath, 'utf8'));

// Public operations only: internal ones (first-party auth, OAuth server, ...)
// aren't part of the SDK surface.
const pub = structuredClone(spec);
for (const [p, item] of Object.entries(pub.paths)) {
	for (const m of Object.keys(item)) {
		if (item[m]['x-linkvite-visibility'] !== 'public') delete item[m];
	}
	if (Object.keys(item).length === 0) delete pub.paths[p];
}

const header = `// Generated by scripts/generate.mjs from spec/openapi.json (API ${spec.info.version}). Do not edit.\n`;

const ast = await openapiTS(pub, {
	alphabetize: true,
	exportType: true,
	immutable: false,
	defaultNonNullable: false,
});
const schemaTs = header + '/* eslint-disable */\n' + astToString(ast);

// ---------------------------------------------------------------- resources
const namespaces = new Map();
const used = new Set();
for (const [p, item] of Object.entries(pub.paths)) {
	for (const [m, op] of Object.entries(item)) {
		const sdk = op['x-linkvite-sdk'];
		if (!sdk) continue;
		if (used.has(sdk)) throw new Error(`duplicate SDK name ${sdk}`);
		used.add(sdk);
		const [ns, method] = sdk.split('.');
		if (!namespaces.has(ns)) namespaces.set(ns, []);
		namespaces
			.get(ns)
			.push({path: p, method: m.toUpperCase(), op, name: method});
	}
}

const ident = s => s.replace(/[^A-Za-z0-9_$]/g, '_');
const jsdoc = (op, extra = []) => {
	const lines = [];
	if (op.summary)
		lines.push(op.summary.endsWith('.') ? op.summary : op.summary + '.');
	if (op.description) lines.push('', ...op.description.split('\n'));
	const meta = [];
	if (op['x-linkvite-scopes']?.length)
		meta.push(`Scope: \`${op['x-linkvite-scopes'].join(', ')}\`.`);
	if (op['x-linkvite-rate-limit'])
		meta.push(`Rate limit: ${op['x-linkvite-rate-limit']}.`);
	if (meta.length) lines.push('', meta.join(' '));
	lines.push(...extra);
	return [
		'/**',
		...lines.map(l => (l ? ` * ${l.replace(/\*\//g, '*\\/')}` : ' *')),
		' */',
	];
};

let out = header;
out += `import type {operations} from './schema';\n`;
out += `import type {Transport, RequestOptions, Data, Body, Query} from '../transport';\n\n`;
out += `/** Every SDK namespace, bound to a transport. */\nexport function createResources(t: Transport) {\n\treturn {\n`;
for (const ns of [...namespaces.keys()].sort()) {
	out += `\t\t${ns}: {\n`;
	const methods = namespaces
		.get(ns)
		.sort((a, b) => a.name.localeCompare(b.name));
	for (const {path: p, method, op, name} of methods) {
		const id = op.operationId;
		const O = `operations['${id}']`;
		const pathParams = [...p.matchAll(/\{([^}]+)\}/g)].map(x => x[1]);
		const queryParams = (op.parameters ?? []).filter(x => x.in === 'query');
		const queryRequired = queryParams.some(x => x.required);
		const hasBody = !!op.requestBody;
		const multipart =
			hasBody && !!op.requestBody.content?.['multipart/form-data'];
		const sig = pathParams.map(x => `${ident(x)}: string`);
		const call = [];
		if (pathParams.length)
			call.push(
				`path: {${pathParams.map(x => (ident(x) === x ? x : `'${x}': ${ident(x)}`)).join(', ')}}`,
			);
		if (hasBody) {
			sig.push(`body: Body<${O}>`);
			call.push('body');
			if (multipart) call.push('multipart: true');
		}
		if (queryParams.length) {
			sig.push(`query${queryRequired ? '' : '?'}: Query<${O}>`);
			call.push('query');
		}
		sig.push('options?: RequestOptions');
		const extra = [];
		for (const x of pathParams)
			extra.push(`@param ${ident(x)} - Path parameter \`${x}\`.`);
		if (multipart)
			extra.push(
				'@param body - Sent as multipart/form-data; pass a Blob or File for file fields.',
			);
		if (extra.length) extra.unshift('');
		out +=
			jsdoc(op, extra)
				.map(l => '\t\t\t' + l)
				.join('\n') + '\n';
		out += `\t\t\t${name}: (${sig.join(', ')}): Promise<Data<${O}>> =>\n`;
		out += `\t\t\t\tt.request<Data<${O}>>('${method}', '${p}', {${call.join(', ')}}, options),\n`;
	}
	out += `\t\t},\n`;
}
out += `\t};\n}\n\nexport type Resources = ReturnType<typeof createResources>;\n\n`;
out += `/** Operation ids by SDK method, for reference and tests. */\nexport const operationIds = {\n`;
for (const ns of [...namespaces.keys()].sort()) {
	for (const {name, op} of namespaces
		.get(ns)
		.sort((a, b) => a.name.localeCompare(b.name))) {
		out += `\t'${ns}.${name}': '${op.operationId}',\n`;
	}
}
out += `} as const;\n`;

// ------------------------------------------------------------------- write
const files = {
	'src/generated/schema.ts': schemaTs,
	'src/generated/resources.ts': out,
};
let stale = false;
for (const [rel, text] of Object.entries(files)) {
	const file = path.join(root, rel);
	if (check) {
		const cur = await readFile(file, 'utf8').catch(() => '');
		if (cur !== text) {
			console.error(`stale: ${rel} (run pnpm generate)`);
			stale = true;
		}
	} else {
		await writeFile(file, text);
	}
}
if (stale) process.exit(1);
console.log(
	check
		? 'generated files are up to date'
		: `generated ${used.size} methods in ${namespaces.size} namespaces from API ${spec.info.version}`,
);
